import{_ as a,o as n,c as t,a3 as e}from"./chunks/framework.MGD2uYU7.js";const g=JSON.parse('{"title":"SC-48 — Quản lý người dùng (admin)","description":"","frontmatter":{"title":"SC-48 — Quản lý người dùng (admin)"},"headers":[],"relativePath":"wireframes/admin/sc-48-quan-ly-nguoi-dung.md","filePath":"wireframes/admin/sc-48-quan-ly-nguoi-dung.md","lastUpdated":1791606799000}'),l={name:"wireframes/admin/sc-48-quan-ly-nguoi-dung.md"};function i(d,s,p,c,o,r){return n(),t("div",null,[...s[0]||(s[0]=[e('<h1 id="sc-48-—-quan-ly-nguoi-dung-admin" tabindex="-1">SC-48 — Quản lý người dùng (admin) <a class="header-anchor" href="#sc-48-—-quan-ly-nguoi-dung-admin" aria-label="Permalink to &quot;SC-48 — Quản lý người dùng (admin)&quot;">​</a></h1><p><span class="wf-badge danger">ADMIN</span> <span class="wf-badge info">Route: /admin/nguoi-dung</span> <span class="wf-badge muted">Nguồn: docs/05 §3 · docs/06 endpoints 52/53/63 + §5 · docs/08 BR-IDT-04/05/07 + BR-AU-16/17 + BR-ADM-04 · docs/03 UC-12 · docs/10 US-ADM-04</span></p><p><strong>Ai xem màn này</strong>: ADMIN/CS An Phuc — tra cứu tài khoản, xử lý vi phạm (suspend/activate), reset mật khẩu theo yêu cầu CS (v1 không có self-service &quot;quên mật khẩu&quot;), phục hồi quyền đấu giá sau forfeit. <strong>Mục đích</strong>: search + DataTable users; drawer hồ sơ 360° (info, KYC, tin, phiên tham gia); <strong>mọi hành động đều reason bắt buộc + toast + audit</strong>; chặn cứng suspend user đang trong phiên LIVE. <strong>Ví dụ số dùng trong bản vẽ</strong>: Nguyễn Văn A (chủ căn <code>CT2-A18.05</code> — tin RESERVED trong phiên DGA-2026-0001) · Trần Thị B (TV-7F2A, registration ACTIVE trong phiên LIVE — ví dụ blocked) · Lê Văn C (SUSPENDED + privilege SUSPENDED do forfeit cọc DGA-2025-0118).</p><h2 id="_1-desktop-—-search-bang-nguoi-dung" tabindex="-1">1. Desktop — search + bảng người dùng <a class="header-anchor" href="#_1-desktop-—-search-bang-nguoi-dung" aria-label="Permalink to &quot;1. Desktop — search + bảng người dùng&quot;">​</a></h2><div class="wf"><div class="wf-screen"><div class="wf-browser-bar"><span class="wf-dot"></span><span class="wf-dot"></span><span class="wf-dot"></span><span class="wf-url">anphuc.vn/admin/nguoi-dung?q=&amp;status=</span></div><div class="wf-body"><div class="wf-row" style="align-items:stretch;gap:0;"><div class="wf-admin-rail"><span class="brand">AnPhuc Admin</span><span class="item">Dashboard</span><span class="item">KYC</span><span class="item">Tin</span><span class="item">Dự án</span><span class="item">Đấu giá</span><span class="item">Thanh toán</span><span class="item active">Người dùng</span><span class="item">Audit</span></div><div class="wf-grow wf-col" style="padding:16px;min-width:0;gap:12px;"><div class="wf-row between middle"><span class="wf-title lg">Người dùng <span class="wf-callout">1</span></span><span class="wf-btn sm ghost">Xuất CSV</span></div><div class="wf-row middle wrap"><div class="wf-search" style="max-width:360px;">🔍 Tìm theo email, tên, SĐT…<span class="caret"></span></div><div class="wf-input" style="min-width:150px;">Trạng thái: Tất cả<span class="caret">▾</span></div><div class="wf-input" style="min-width:150px;">KYC: Tất cả<span class="caret">▾</span></div><div class="wf-input" style="min-width:170px;">Quyền đấu giá: Tất cả<span class="caret">▾</span></div></div><table class="wf-table"><thead><tr><th>Người dùng</th><th>Tài khoản</th><th>KYC</th><th>Quyền đấu giá</th><th>Tin</th><th>Phiên tham gia</th><th>Đăng nhập cuối</th><th></th></tr></thead><tbody><tr><td><b>Nguyễn Văn A</b><br><span class="wf-small">nguyen.van.a@example.com · 09xx-xxx-101</span></td><td><span class="wf-badge ok">ACTIVE</span></td><td><span class="wf-badge ok">APPROVED</span></td><td><span class="wf-badge ok">GRANTED</span></td><td>1<br><span class="wf-small">CT2-A18.05 · RESERVED</span></td><td>0</td><td>10/10/2026 09:12</td><td><span class="wf-btn sm">Xem</span></td></tr><tr><td><b>Trần Thị B</b><br><span class="wf-small">tran.thi.b@example.com · 09xx-xxx-214</span></td><td><span class="wf-badge ok">ACTIVE</span></td><td><span class="wf-badge ok">APPROVED</span></td><td><span class="wf-badge ok">GRANTED</span></td><td>0</td><td>2 <span class="wf-badge danger live">đang trong phiên LIVE</span> <span class="wf-callout">2</span></td><td>10/10/2026 14:20</td><td><span class="wf-btn sm">Xem</span></td></tr><tr><td><b>Lê Văn C</b><br><span class="wf-small">le.van.c@example.com · 09xx-xxx-337</span></td><td><span class="wf-badge danger">SUSPENDED</span></td><td><span class="wf-badge ok">APPROVED</span></td><td><span class="wf-badge danger">SUSPENDED</span><br><span class="wf-small">forfeit DGA-2025-0118</span></td><td>0</td><td>3</td><td>07/10/2026 20:41</td><td><span class="wf-btn sm">Xem</span></td></tr><tr><td><b>Phạm Thu D</b><br><span class="wf-small">pham.thu.d@example.com</span></td><td><span class="wf-badge ok">ACTIVE</span></td><td><span class="wf-badge warn">PENDING</span></td><td><span class="wf-badge muted">GRANTED</span><br><span class="wf-small">chưa dùng (KYC chưa xong)</span></td><td>0</td><td>0</td><td>10/10/2026 08:02</td><td><span class="wf-btn sm">Xem</span></td></tr><tr><td><b>—</b><br><span class="wf-small">vo.danh92@example.com</span></td><td><span class="wf-badge ok">ACTIVE</span></td><td><span class="wf-badge muted">NONE</span></td><td><span class="wf-badge muted">GRANTED</span></td><td>0</td><td>0</td><td>01/10/2026 22:17</td><td><span class="wf-btn sm">Xem</span></td></tr></tbody></table><div class="wf-row between middle"><span class="wf-small">Trang 1/48 · 952 users · search q khớp email/tên/SĐT không phân biệt hoa thường <span class="wf-callout">3</span></span><div class="wf-pagination" style="margin-top:0;"><span class="pg">‹</span><span class="pg active">1</span><span class="pg">2</span><span class="pg">3</span><span class="pg">…</span><span class="pg">48</span><span class="pg">›</span></div></div></div></div><div class="wf-footer"><span>AnPhucRealEstate — sàn NOXH được vận hành bởi An Phuc</span><span>Quy chế đấu giá</span><span>CSKH 1900-xxx</span></div></div></div></div><div class="wf-legend"><div class="t">Chú thích hành vi (trace: docs/03 UC-12 · docs/02 FR-ADM-03 · docs/06 endpoint 52)</div><ol><li><span class="num">1</span><span><b>Server-side DataTable</b> <code>GET /admin/users?q=&amp;status=&amp;page=</code>: search debounce 400ms, filter đổi là refetch, URL sync query. KHÔNG có nút &quot;Tạo user&quot; — tài khoản chỉ sinh qua đăng ký công khai (SC-10). <span class="ref">FR-ADM-03</span></span></li><li><span class="num">2</span><span><b>Cột &quot;Phiên tham gia&quot; gắn badge live</b> khi user có registration ACTIVE trong phiên IN_PROGRESS — tín hiệu sớm cho biết user này <b>không suspend được</b> (mục 4). <span class="ref">BR-IDT-05</span></span></li><li><span class="num">3</span><span>Hiển thị 2 trạng thái độc lập: <b>tài khoản</b> (ACTIVE/SUSPENDED — mutation nghiệp vụ) và <b>quyền đấu giá</b> (GRANTED/SUSPENDED — privilege riêng, forfeit job tự gắn, chỉ ADMIN restore). KYC là cột riêng vì gate nhiều quyền (BR-KYC-08). <span class="ref">BR-AU-16</span> <span class="ref">docs/07 §2.1</span></span></li></ol></div><h2 id="_2-drawer-ho-so-user-—-thong-tin-kyc-tin-phien" tabindex="-1">2. Drawer hồ sơ user — thông tin, KYC, tin, phiên <a class="header-anchor" href="#_2-drawer-ho-so-user-—-thong-tin-kyc-tin-phien" aria-label="Permalink to &quot;2. Drawer hồ sơ user — thông tin, KYC, tin, phiên&quot;">​</a></h2><div class="wf"><div class="wf-row" style="align-items:flex-start;gap:0;"><div class="wf-grow" style="opacity:0.35;padding:16px;"><table class="wf-table"><thead><tr><th>Người dùng</th><th>Tài khoản</th><th>KYC</th><th>Quyền đấu giá</th></tr></thead><tbody><tr><td><b>Nguyễn Văn A</b><br><span class="wf-small">nguyen.van.a@example.com</span></td><td><span class="wf-badge ok">ACTIVE</span></td><td><span class="wf-badge ok">APPROVED</span></td><td><span class="wf-badge ok">GRANTED</span></td></tr><tr><td><b>Trần Thị B</b><br><span class="wf-small">tran.thi.b@example.com</span></td><td><span class="wf-badge ok">ACTIVE</span></td><td><span class="wf-badge ok">APPROVED</span></td><td><span class="wf-badge ok">GRANTED</span></td></tr></tbody></table><span class="wf-small">(bảng phía sau làm mờ — drawer trượt phải, đóng bằng ESC/nút ×)</span></div><div class="wf-drawer wf-col" style="gap:10px;width:400px;"><div class="wf-row between middle"><span class="wf-row middle" style="gap:8px;"><span class="wf-avatar">NA</span><span class="wf-title">Nguyễn Văn A</span></span><span class="wf-badge ok">ACTIVE</span></div><div class="wf-col" style="gap:2px;"><span class="wf-small">nguyen.van.a@example.com · 09xx-xxx-101 · <span class="wf-trace">usr_01J8K2M9Q4</span></span><span class="wf-small">Tham gia 12/03/2026 · đăng nhập cuối 10/10/2026 09:12 (GMT+7) <span class="wf-callout">4</span></span></div><div class="wf-row wrap" style="gap:6px;"><span class="wf-badge ok">KYC APPROVED</span><span class="wf-badge ok">Quyền đấu giá GRANTED</span><span class="wf-badge muted">Gói FREE</span></div><div class="wf-col" style="gap:2px;border-top:1px solid var(--wf-line);padding-top:8px;"><span class="wf-small wf-muted">KYC</span><span class="wf-small">APPROVED 13/03/2026 bởi admin.tran · CCCD 031***456 (redacted) <span class="wf-callout">5</span></span></div><div class="wf-col" style="gap:2px;border-top:1px solid var(--wf-line);padding-top:8px;"><span class="wf-small wf-muted">TIN ĐĂNG (1)</span><span class="wf-small">CT2-A18.05 — NOXH HP-380 · <span class="wf-badge info">RESERVED</span> · đang trong phiên DGA-2026-0001 <span class="wf-accent">→ monitor SC-46</span></span></div><div class="wf-col" style="gap:2px;border-top:1px solid var(--wf-line);padding-top:8px;"><span class="wf-small wf-muted">PHIÊN THAM GIA (0)</span><span class="wf-small">Chưa đăng ký phiên nào — là chủ tin CT2-A18.05 nên không được bid phiên của chính mình <span class="wf-callout">6</span></span></div><div class="wf-col" style="gap:2px;border-top:1px solid var(--wf-line);padding-top:8px;"><span class="wf-small wf-muted">ORDER (0 đang chờ)</span><span class="wf-small">Lịch sử: không có</span></div><div class="wf-col" style="gap:8px;border-top:2px solid var(--wf-line-strong);padding-top:10px;"><span class="wf-btn danger block">Tạm ngưng tài khoản (SUSPEND) <span class="wf-callout" style="background:#fff;color:var(--wf-danger);">7</span></span><span class="wf-btn ghost block">Reset mật khẩu (theo yêu cầu CS)</span><span class="wf-small wf-center wf-muted">Admin không sửa được thông tin user (tên/SĐT/email) — user tự sửa; ops chỉ xử lý qua CS <span class="wf-callout">8</span></span></div></div></div></div><div class="wf-legend"><div class="t">Chú thích</div><ol><li><span class="num">4</span><span>Drawer = hồ sơ 360° read-first: info định danh, KYC, tin, phiên tham gia, order — dữ liệu UC-12 MF yêu cầu trước khi quyết định suspend/activate. <span class="ref">UC-12</span></span></li><li><span class="num">5</span><span>CCCD luôn <b>redacted</b> ở mọi màn admin ngoài queue KYC (NFR-S-05); xem đầy đủ chỉ ở SC-41 khi duyệt và mọi lần xem ghi audit. <span class="ref">NFR-S-05</span></span></li><li><span class="num">6</span><span>Giải thích ngay trong drawer vì sao 0 phiên: chủ tin bị loại khỏi phiên của chính mình (điều kiện đăng ký) — tránh admin tưởng bug. <span class="ref">BR-AU-05</span></span></li><li><span class="num">7</span><span>Action set đổi theo trạng thái: ACTIVE → [Suspend] · SUSPENDED → [Kích hoạt lại] · privilege SUSPENDED → thêm [Phục hồi quyền đấu giá] (RESTORE_AUCTION_PRIVILEGE — reason bắt buộc, audit; chỉ ADMIN mở lại được sau forfeit). <span class="ref">endpoint 53</span> <span class="ref">BR-AU-16</span></span></li><li><span class="num">8</span><span><b>Không có form edit user</b> — permission matrix: admin ⛔ &quot;sửa hộ&quot; hồ sơ. Drawer chỉ có action trạng thái + reset mật khẩu. <span class="ref">docs/08 §9</span></span></li></ol></div><h2 id="_3-modal-suspend-—-reason-bat-buoc-he-qua" tabindex="-1">3. Modal suspend — reason bắt buộc + hệ quả <a class="header-anchor" href="#_3-modal-suspend-—-reason-bat-buoc-he-qua" aria-label="Permalink to &quot;3. Modal suspend — reason bắt buộc + hệ quả&quot;">​</a></h2><div class="wf"><div class="wf-modal-overlay"><div class="wf-modal"><div class="head" style="color:var(--wf-danger);">Tạm ngưng tài khoản le.van.c@example.com?</div><div class="wf-lines" style="margin:8px 0;"><div class="wf-row between"><span class="wf-text">Trạng thái hiện tại</span><span class="wf-badge ok">ACTIVE</span></div><div class="wf-row between"><span class="wf-text">KYC / Quyền đấu giá</span><span>APPROVED · GRANTED</span></div><div class="wf-row between"><span class="wf-text">Phiên LIVE đang tham gia</span><span class="wf-ok-text">Không có — đủ điều kiện suspend <span class="wf-callout">9</span></span></div></div><div class="wf-note" style="background:var(--wf-danger-soft);border-color:var(--wf-danger);color:var(--wf-danger);margin:0;"> Hệ quả: user <b>vẫn đăng nhập được</b> nhưng mọi thao tác nghiệp vụ (đăng tin, bid, đặt cọc, mua gói) bị chặn 403; read-only public vẫn dùng được. Kích hoạt lại bất kỳ lúc nào (cũng cần lý do). <span class="wf-callout danger">10</span></div><span class="wf-small wf-strong" style="display:block;margin-top:10px;">Lý do (bắt buộc, 5–500 ký tự — ghi audit, hiện nguyên văn khi user khiếu nại qua CS)</span><div class="wf-input filled" style="min-height:64px;align-items:flex-start;">Trúng giá DGA-2025-0118 nhưng không thanh toán trong 24h — forfeit cọc, ticket CS-102, tạm ngưng chờ xác minh thêm<span class="caret">✎</span></div><div class="wf-row between" style="margin-top:4px;"><span class="wf-small">103/500 ký tự</span><span class="wf-small wf-muted">Audit USER_SUSPEND — bất biến, xem tại SC-49</span></div><div class="wf-row" style="margin-top:12px;"><span class="wf-btn" style="flex:1;">Quay lại</span><span class="wf-btn danger" style="flex:1;">TẠM NGƯNG TÀI KHOẢN</span></div></div></div></div><div class="wf-legend"><div class="t">Chú thích</div><ol><li><span class="num">9</span><span>Modal <b>pre-check công khai</b> &quot;Phiên LIVE đang tham gia: Không có&quot; — nếu có, nút danger thay bằng trạng thái blocked (mục 4). Server vẫn re-check: 409 <code>USER_HAS_ACTIVE_AUCTION</code> nếu race (user vừa vào ACTIVE giữa lúc admin mở modal). <span class="ref">BR-IDT-05</span> <span class="ref">UC-12 EF</span></span></li><li><span class="num">10</span><span>Hệ quả theo BR-IDT-07 (login được, mutation 403 <code>USER_SUSPENDED</code>) — không dọa chung chung. Reason 5–500 ký tự: dưới 5 → field error &quot;Lý do tối thiểu 5 ký tự&quot; + disable nút. Thành công → toast ok <b>&quot;Đã tạm ngưng le.van.c@example.com — lý do đã ghi audit&quot;</b>; ACTIVATE → <b>&quot;Đã kích hoạt lại tài khoản&quot;</b>. Race 409 → toast đỏ message server + refresh drawer. <span class="ref">BR-IDT-04</span> <span class="ref">endpoint 53</span> <span class="ref">docs/06 §5</span></span></li></ol></div><h2 id="_4-blocked-state-—-khong-suspend-đuoc-user-đang-trong-phien-live" tabindex="-1">4. Blocked state — KHÔNG suspend được user đang trong phiên LIVE <a class="header-anchor" href="#_4-blocked-state-—-khong-suspend-đuoc-user-đang-trong-phien-live" aria-label="Permalink to &quot;4. Blocked state — KHÔNG suspend được user đang trong phiên LIVE&quot;">​</a></h2><div class="wf"><div class="wf-col" style="max-width:640px;"><div class="wf-toast danger"><b>User đang tham gia phiên chưa kết thúc — không thể suspend</b> <span class="wf-callout danger">11</span></div><div class="wf-card"><div class="pad wf-col" style="gap:8px;"><div class="wf-row between middle"><span class="wf-row middle" style="gap:8px;"><span class="wf-avatar">TB</span><span class="wf-title">Trần Thị B</span></span><span class="wf-badge ok">ACTIVE</span></div><div class="wf-note" style="margin:0;background:var(--wf-danger-soft);border-color:var(--wf-danger);color:var(--wf-danger);"> Đang có registration <b>ACTIVE</b> trong phiên <b>DGA-2026-0001</b> (IN_PROGRESS · căn CT2-A18.05) — bí danh <b>TV-7F2A</b>, hiện là leader 1.926.000.000 ₫. Suspend lúc này phá vỡ phiên đấu và tiền cọc đang giữ. <span class="wf-callout danger">12</span></div><div class="wf-row" style="gap:8px;"><span class="wf-btn danger disabled" style="flex:1;">Tạm ngưng tài khoản (bị khóa)</span><span class="wf-btn" style="flex:1;">Ngưng quyền đấu giá (privilege) <span class="wf-callout">13</span></span></div><span class="wf-small">Nút suspend disabled + tooltip nguyên văn message 409. Đường đi đúng: <b>(a)</b> ngưng quyền đấu giá ngay giữa phiên nếu vi phạm đấu giá — bid đã ghi <b>vẫn giữ giá trị</b> (không hồi tố), user không bid tiếp được nữa (màn SC-06 của user hiện panel 403); <b>(b)</b> chờ phiên kết thúc rồi suspend tài khoản nếu vẫn cần. <span class="wf-callout">14</span></span><span class="wf-small wf-accent">Xem phiên của user → SC-46 monitor DGA-2026-0001</span></div></div></div></div><div class="wf-legend"><div class="t">Chú thích</div><ol><li><span class="num">11</span><span>Toast/banner dùng <b>đúng message chuẩn docs/06 §5</b> cho <code>USER_HAS_ACTIVE_AUCTION</code>: &quot;User đang tham gia phiên chưa kết thúc — không thể suspend&quot; — không tự viết lại. <span class="ref">docs/06 §5</span></span></li><li><span class="num">12</span><span>Blocked state phải <b>giải thích + chỉ đường đi thay thế</b>, không chỉ disable nút: hiện phiên nào, bí danh gì, đang dẫn đầu hay không — admin ra quyết định có ngữ cảnh. <span class="ref">BR-IDT-05</span></span></li><li><span class="num">13</span><span><b>Privilege flag, không phải account suspend</b>: vi phạm giữa phiên xử bằng quyền đấu giá (SUSPENDED) — bid đã submit giữ nguyên giá trị, không được bid tiếp; không ảnh hưởng order cũ. Privilege thường do job forfeit tự gắn (BR-AU-15); thao tác ngưng-giữa-phiên bằng tay cần bổ sung action endpoint 53 khi implement (đề xuất ghi docs/06 qua PR — wireframe vẽ sẵn vị trí). <span class="ref">BR-AU-16/17</span> <span class="ref">SC-06 callout 15</span></span></li><li><span class="num">14</span><span>Defense in depth: kể cả khi FE bị bypass, <code>PATCH /admin/users/{id}</code> SUSPEND vẫn trả 409 — UI không phải chốt chặn duy nhất. <span class="ref">FR-ADM-03</span></span></li></ol></div><h2 id="_5-reset-mat-khau-us-adm-04-br-adm-04-—-modal-ket-qua-1-lan" tabindex="-1">5. Reset mật khẩu (US-ADM-04 / BR-ADM-04) — modal + kết quả 1 lần <a class="header-anchor" href="#_5-reset-mat-khau-us-adm-04-br-adm-04-—-modal-ket-qua-1-lan" aria-label="Permalink to &quot;5. Reset mật khẩu (US-ADM-04 / BR-ADM-04) — modal + kết quả 1 lần&quot;">​</a></h2><div class="wf"><div class="wf-row" style="gap:16px;align-items:flex-start;flex-wrap:wrap;"><div class="wf-col" style="flex:1;min-width:320px;"><span class="wf-state-label">MODAL RESET — NHẬP LÝ DO</span><div class="wf-modal-overlay" style="padding:16px;"><div class="wf-modal"><div class="head">Reset mật khẩu — nguyen.van.a@example.com? <span class="wf-callout">15</span></div><span class="wf-small">v1 không có &quot;quên mật khẩu&quot; self-service: user gọi CSKH 1900-xxx, CS xác minh CCCD rồi ADMIN thực hiện theo yêu cầu (UC-01 AF-3).</span><div class="wf-lines" style="margin:8px 0;"><div class="wf-row between"><span class="wf-text">Tài khoản</span><span class="wf-badge ok">ACTIVE</span></div><div class="wf-row between"><span class="wf-text">Refresh token đang hiệu lực</span><span class="wf-strong">2 (sẽ thu hồi hết)</span></div></div><div class="wf-note" style="margin:0 0 8px;">Hệ quả: sinh <b>mật khẩu tạm dùng 1 lần</b> · user <b>bắt buộc đổi ở lần đăng nhập đầu</b> (mọi API khác 403 tới khi đổi) · thu hồi toàn bộ refresh token family · audit <code>USER_RESET_PASSWORD</code> (KHÔNG lưu mật khẩu tạm trong diff). <span class="wf-callout">16</span></div><span class="wf-small wf-strong">Lý do / số yêu cầu CS (bắt buộc, 5–500 ký tự)</span><div class="wf-input filled" style="min-height:56px;align-items:flex-start;">YC-88 CS Nguyễn — user gọi hotline xác minh CCCD<span class="caret">✎</span></div><div class="wf-row" style="margin-top:12px;"><span class="wf-btn" style="flex:1;">Quay lại</span><span class="wf-btn danger" style="flex:1;">RESET MẬT KHẨU</span></div></div></div></div><div class="wf-col" style="flex:1;min-width:320px;"><span class="wf-state-label">KẾT QUẢ (200) — MẬT KHẨU TẠM CHỈ HIỆN 1 LẦN</span><div class="wf-modal-overlay" style="padding:16px;"><div class="wf-modal"><div class="head" style="color:var(--wf-ok);">✓ Đã reset — gửi mật khẩu tạm cho user qua kênh CS</div><div class="wf-input filled" style="font-family:ui-monospace, Menlo, monospace;justify-content:center;font-size:16px;letter-spacing:1px;">Xk9!mQ2#vT<span class="caret">⧉ Sao chép</span></div><div class="wf-note" style="background:var(--wf-danger-soft);border-color:var(--wf-danger);color:var(--wf-danger);margin:8px 0 0;"><b>Chỉ hiện lần này — không lưu ở bất kỳ đâu</b> (không audit, không log, không xem lại được). Đóng modal là mất; nếu thất lạc phải reset lần nữa. <span class="wf-callout danger">17</span></div><div class="wf-lines" style="margin:8px 0;"><div class="wf-row between"><span class="wf-text">Đã thu hồi refresh token</span><span class="wf-strong">2</span></div><div class="wf-row between"><span class="wf-text">Bắt buộc đổi mật khẩu</span><span class="wf-ok-text">BẬT — login lần đầu sẽ bị chặn tới khi đổi</span></div><div class="wf-row between"><span class="wf-text">Audit</span><span class="wf-trace">log_01J9ZT8K1 → SC-49</span></div></div><span class="wf-btn primary block">ĐÃ SAO XÉP — ĐÓNG</span></div></div><span class="wf-state-label">USER ĐANG SUSPENDED — NÚT RESET KHÓA</span><div class="wf-card"><div class="pad wf-col"><span class="wf-btn disabled block">Reset mật khẩu (khóa)</span><span class="wf-small">Server trả 403 <code>USER_SUSPENDED</code> — không reset cho tài khoản đang tạm ngưng; kích hoạt lại trước nếu chính đáng. Message user-side khi login bằng mật khẩu tạm: &quot;Tài khoản vừa được đặt lại mật khẩu — vui lòng đổi mật khẩu trước khi tiếp tục&quot;. <span class="wf-callout">18</span></span></div></div></div></div></div><div class="wf-legend"><div class="t">Chú thích</div><ol><li><span class="num">15</span><span>Reset password là hành động nhạy cảm: nút danger, modal nêu đủ hệ quả trước khi bấm, reason gắn số yêu cầu CS để audit truy được chuỗi trách nhiệm. <span class="ref">BR-ADM-04</span> <span class="ref">US-ADM-04</span></span></li><li><span class="num">16</span><span>Force-change gate: <code>password_must_change = true</code> — login OK nhưng mọi API khác 403 <code>AUTH_PASSWORD_MUST_CHANGE</code> tới khi đổi (FE user bắt 403 → chuyển hướng màn đổi mật khẩu). <span class="ref">FR-IDT-07</span> <span class="ref">docs/07 §2.1</span></span></li><li><span class="num">17</span><span><b>tempPassword chỉ trả 1 lần trong response</b>, không lưu audit/log — modal kết quả không có nút &quot;xem lại&quot;, đóng không hỏi lần hai (admin đã được cảnh báo copy trước). <span class="ref">BR-ADM-04</span> <span class="ref">docs/06 §4.8b</span></span></li><li><span class="num">18</span><span>Mọi message user-facing trong flow này lấy verbatim docs/06 §5 (<code>AUTH_PASSWORD_MUST_CHANGE</code>). Toast admin thành công: <b>&quot;Đã reset mật khẩu nguyen.van.a@example.com — mật khẩu tạm chỉ hiện 1 lần, đã thu hồi 2 refresh token&quot;</b> + audit. <span class="ref">docs/06 §5</span> <span class="ref">endpoint 63</span></span></li></ol></div><h2 id="_6-empty-loading-error-checklist-designer" tabindex="-1">6. Empty / Loading / Error + Checklist designer <a class="header-anchor" href="#_6-empty-loading-error-checklist-designer" aria-label="Permalink to &quot;6. Empty / Loading / Error + Checklist designer&quot;">​</a></h2><div class="wf"><div class="wf-grid cols-3"><div class="wf-col"><span class="wf-state-label">EMPTY — SEARCH KHÔNG RA</span><div class="wf-empty"><b>Không tìm thấy user khớp &quot;nguyen van z&quot;</b><br><span class="wf-small">Thử email đầy đủ, tên không dấu, hoặc SĐT 9–10 số.</span><div style="margin-top:10px;"><span class="wf-btn sm">Xóa bộ lọc</span></div></div></div><div class="wf-col"><span class="wf-state-label">LOADING — SKELETON</span><div class="wf-card"><div class="pad wf-col"><div class="wf-skeleton" style="height:38px;"></div><div class="wf-skeleton" style="height:26px;"></div><div class="wf-skeleton" style="height:26px;"></div><div class="wf-skeleton" style="height:26px;"></div><span class="wf-small">Skeleton search + 8 dòng bảng; drawer mở sẵn thì skeleton theo khối.</span></div></div></div><div class="wf-col"><span class="wf-state-label">ERROR — 409 KHI SUSPEND (RACE)</span><div class="wf-error-box" style="text-align:left;padding:12px;"><b>Không thể tạm ngưng — trạng thái vừa thay đổi</b><br><span class="wf-small">User vừa vào registration ACTIVE của phiên LIVE giữa lúc bạn mở modal (409 USER_HAS_ACTIVE_AUCTION) — drawer refresh, nút suspend chuyển blocked (mục 4).</span><br><span class="wf-trace">traceId: 71aa0c5d-3e8b-49f2</span><div style="margin-top:8px;"><span class="wf-btn sm">Thử lại</span></div></div></div></div></div><p><strong>Checklist designer khi dựng Figma cho SC-48</strong></p><ul><li>[ ] Search + 3 filter (status/KYC/privilege) + bảng 8 cột; badge live &quot;đang trong phiên LIVE&quot; ở cột phiên</li><li>[ ] Drawer hồ sơ 360°: info · KYC (CCCD redacted) · tin · phiên tham gia · order · action set đổi theo trạng thái (Suspend / Kích hoạt / Phục hồi quyền đấu giá / Reset mật khẩu)</li><li>[ ] Modal suspend: pre-check &quot;phiên LIVE: không có&quot;, reason textarea 5–500 + counter, hệ quả BR-IDT-07 bằng chữ thật, nút danger + loading</li><li>[ ] Frame blocked (mục 4): nút disabled + toast verbatim &quot;User đang tham gia phiên chưa kết thúc — không thể suspend&quot; + nút thay thế &quot;Ngưng quyền đấu giá&quot; + giải thích bid giữ giá trị</li><li>[ ] Reset mật khẩu: 3 frame (modal reason → kết quả tempPassword 1-lần → SUSPENDED khóa nút); copy kết quả đúng docs/06 §4.8b (tempPassword, revokedRefreshCount, mustChangePassword)</li><li>[ ] Toast đủ: suspend ok · activate ok · blocked 409 · reset ok · reset 403 USER_SUSPENDED — mọi mutation kèm &quot;đã ghi audit&quot;</li><li>[ ] 4-state: skeleton / empty (kèm gợi ý cú pháp search) / error+traceId / data</li><li>[ ] Responsive note: desktop-priority; ≤768px drawer full-width, bảng cuộn ngang giữ cột hành động</li><li>[ ] Không emoji icon production (🔍/✓ là placeholder); ngày <code>dd/MM/yyyy HH:mm</code> + GMT+7; SĐT/email mask một phần ở bản Figma public</li></ul><div class="info custom-block"><p class="custom-block-title">Góp ý màn này?</p><p>Comment ngay bên dưới — ghi rõ khu vực (số callout) và đề xuất. Thay đổi nghiệp vụ cần PM duyệt trên docs/08 trước.</p></div>',23)])])}const u=a(l,[["render",i]]);export{g as __pageData,u as default};
